/**
 * Creates a debounced version of the provided function that delays its
 * execution until after `delay` milliseconds have elapsed since the last
 * time the debounced function was invoked.
 *
 * @param {Function} func - The function to debounce.
 * @param {number} delay - The number of milliseconds to wait after the last
 *   invocation before executing `func`.
 * @returns {Function} The debounced function. It preserves the `this` context
 *   and arguments of the most recent invocation, and exposes a `cancel()`
 *   method to clear any pending execution.
 */
function debounce(func, delay) {
  /** @type {ReturnType<typeof setTimeout> | null} */
  let timeoutId = null;

  /**
   * The debounced function.
   *
   * @this {*} The context the debounced function is invoked with.
   * @param {...*} args - Arguments to forward to `func`.
   * @returns {void}
   */
  function debounced(...args) {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      func.apply(this, args);
    }, delay);
  }

  /**
   * Cancels any pending execution of the debounced function.
   *
   * @returns {void}
   */
  debounced.cancel = function cancel() {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debounced;
}
